export function getStoryById(id: string): Story | undefined {
  return STORIES.find((s) => s.id === id);
}

const DAY_MS = 86400000;

/** Publish instant (ms). Date-only stories fall back to that date at 00:00 Haiti time (-04:00), so the badge ends at day's end. */
function publishMs(story: Story): number {
  if (story.publishedTime) {
    const t = Date.parse(story.publishedTime);
    if (!Number.isNaN(t)) return t;
  }
  return Date.parse(`${story.publishedAt.slice(0, 10)}T00:00:00-04:00`);
}

/** Newest first by publish time; ties keep array order. */
export function sortNewestFirst(list: Story[]): Story[] {
  return list
    .map((s, i) => ({ s, i, t: publishMs(s) }))
    .sort((a, b) => (a.t === b.t ? a.i - b.i : b.t - a.t))
    .map((x) => x.s);
}

/** Instant the Nouveau/Nouvo badge expires (24h after publishedTime). */
export function newStoryExpiresMs(story: Story): number {
  return publishMs(story) + DAY_MS;
}

/**
 * "New" = less than 24h since publishedTime.
 * Computed at render time from the clock (pass `now` from the browser) so the
 * badge drops without a redeploy. Date-only stories: 24h from that date at 00:00 Haiti time.
 */
export function isNewStory(story: Story, now = Date.now()): boolean {
  if (story.quiet) return false;
  const t = publishMs(story);
  const age = now - t;
  return age >= 0 && age < DAY_MS;
}

/** How many stories each topic shows on the front page (leads excluded). */
export const FRONT_PAGE_PER_SECTION = 4;

function isBajAuthor(story: Story): boolean {
  const a = `${story.author?.fr ?? ""} ${story.author?.ht ?? ""}`;
  return /\bBAJ\b/.test(a) || /Blaise A(?:ntoine)?\.? Joseph/i.test(a);
}

/** BAJ signed opinion (Opinion/Opinyon), whether or not it is still on the front. */
export function isBajOpinion(story: Story): boolean {
  return !!story.isOpinion && isBajAuthor(story);
}

/** 7 days after publishedTime: the story leaves the front and section lists. */
export const ARCHIVE_MS = 7 * DAY_MS;

/** Instant a story is auto-archived (7 days after publishedTime). */
export function storyArchivesAtMs(story: Story): number {
  return publishMs(story) + ARCHIVE_MS;
}

/**
 * Hidden from the front page and section lists.
 * `archived: true` archives early. Otherwise every story, including BAJ
 * opinions and current or former pins, archives 7 days after publishedTime.
 * Computed from the clock so it happens without a redeploy.
 */
export function isArchived(story: Story, now = Date.now()): boolean {
  if (story.archived) return true;
  return now >= storyArchivesAtMs(story);
}

/** Soonest future auto-archive among stories not already flagged archived. */
export function nextArchiveMs(now = Date.now()): number | undefined {
  let next: number | undefined;
  for (const s of STORIES) {
    if (s.archived) continue;
    const at = storyArchivesAtMs(s);
    if (at > now && (next == null || at < next)) next = at;
  }
  return next;
}

/** Newest BAJ opinion still within the 7-day window, by publishedTime. */
export function newestBajOpinion(now = Date.now()): Story | undefined {
  const list = STORIES.filter((s) => isBajOpinion(s) && !isArchived(s, now));
  return sortByPublishedTime(list)[0];
}

/**
 * How many stories sit in the Need to Know strip. The newest BAJ opinion,
 * if one is still within 7 days, is always #1. The remaining slots are the
 * newest non-archived news stories. No news story may be pinned or held
 * at the top. Sports never take a lead slot; they live only in the Sports
 * section. Older BAJ opinions stay in their section, not in this strip.
 * Leads sit above the section blocks and do not count against
 * FRONT_PAGE_PER_SECTION.
 */
export const FRONT_PAGE_LEAD_COUNT = 4;

/** Lead ids in display order: newest BAJ opinion first, then newest news. */
function frontPageLeadIds(now = Date.now()): string[] {
  const featured = newestBajOpinion(now);
  const ids: string[] = featured ? [featured.id] : [];
  const rest = sortByPublishedTime(
    STORIES.filter((s) => !isArchived(s, now) && s.topic !== "sports" && !isBajOpinion(s) && s.id !== featured?.id),
  );
  for (const s of rest) {
    if (ids.length >= FRONT_PAGE_LEAD_COUNT) break;
    ids.push(s.id);
  }
  return ids;
}

export function frontPageLeads(now = Date.now()): Story[] {
  const leads: Story[] = [];
  for (const id of frontPageLeadIds(now)) {
    const story = STORIES.find((s) => s.id === id);
    if (story && !isArchived(story, now)) leads.push(story);
  }
  return leads;
}

export function needToKnowStories(now = Date.now()): Story[] {
  // Standing rule: Sports stories never take top-story (Need to Know) slots; they live only in the Sports section.
  // The newest BAJ opinion is always #1 while it is within 7 days; newest news follows.
  const list = sortNewestFirst(STORIES.filter((s) => !isArchived(s, now) && s.tier === "need-to-know" && s.topic !== "sports"));
  frontPageLeadIds(now).forEach((id, pos) => {
    const at = list.findIndex((s) => s.id === id);
    if (at > pos) {
      const [item] = list.splice(at, 1);
      list.splice(pos, 0, item);
    }
  });
  return list;
}

export function quickHitStories(now = Date.now()): Story[] {
  return sortNewestFirst(STORIES.filter((s) => !isArchived(s, now) && (s.tier === "quick-hit" || s.topic === "sports")));
}

/** Newest first by publish time only. */
function sortByPublishedTime(list: Story[]): Story[] {
  return list
    .map((s, i) => ({ s, i, t: publishMs(s) }))
    .sort((a, b) => (a.t === b.t ? a.i - b.i : b.t - a.t))
    .map((x) => x.s);
}

/** All non-archived stories in a topic, newest first (for section pages). */
export function sectionPageStories(topic: TopicId, now = Date.now()): Story[] {
  return sortByPublishedTime(STORIES.filter((s) => !isArchived(s, now) && s.topic === topic));
}

/**
 * Stories for a topic block on the front page: newest first, excluding the
 * current leads (those already sit at the top), capped at FRONT_PAGE_PER_SECTION.
 */
export function frontPageSectionStories(topic: TopicId, now = Date.now(), limit = FRONT_PAGE_PER_SECTION): Story[] {
  const leadIds = new Set(frontPageLeads(now).map((s) => s.id));
  return sectionPageStories(topic, now).filter((s) => !leadIds.has(s.id)).slice(0, limit);
}

export function breakingExpiresMs(story: Story): number {
  return publishMs(story) + (story.breakingHours ?? 6) * 3600000;
}
export function isBreakingActive(story: Story, now = Date.now()): boolean {
  if (!story.isBreaking) return false;
  const t = publishMs(story);
  return now >= t && now < breakingExpiresMs(story);
}

export function isUrgentActive(story: Story, now = Date.now()): boolean {
  // Standing rule (23 Nov 2026): BAJ opinions in Justice always show URGENT / IJAN.
  if (isBajOpinion(story) && story.topic === "justice") return true;
  if (!story.isUrgent) return false;
  if (story.urgentHours == null) return true;
  const t = publishMs(story);
  return now >= t && now < t + story.urgentHours * 3600000;
}
